   142→            cursor: pointer;
   143→            display: flex;
   144→            align-items: center;
   145→            gap: 6px;
   146→        }
   147→
   148→        .agent-inline-header:hover {
   149→            background: #21262d;
   150→        }
   151→
   152→        .agent-inline-header .agent-icon {
   153→            color: #a371f7;
   154→            font-size: 10px;
   155→        }
   156→
   157→        .agent-inline-header .agent-title {
