   181→            margin-bottom: 4px;
   182→        }
   183→
   184→        .agent-inline-content .message-content {
   185→            font-size: 11px;
   186→            padding: 3px 6px;
   187→            max-height: 300px;
   188→            overflow-y: auto;
   189→        }
   190→
   191→        .agent-inline-content .message-role {
   192→            font-size: 9px;
   193→        }
   194→
   195→        .agent-inline-content .message-time {
   196→            font-size: 10px;
   197→        }
   198→
   199→        .agent-inline-content .tool-header {
   200→            font-size: 10px;
   201→        }
   202→
   203→        .agent-inline-content .tool-input,
   204→        .agent-inline-content .tool-result-content {
