   222→            font-size: 13px;
   223→            color: #58a6ff;
   224→            border-bottom: 1px solid #30363d;
   225→        }
   226→
   227→        .back-btn:hover {
   228→            background: #30363d;
   229→        }
   230→
   231→        /* Main content */
   232→        .main-content {
   233→            flex: 1;
   234→            display: flex;
   235→            flex-direction: column;
   236→            overflow: hidden;
   237→            background: #0d1117;
   238→        }
   239→
   240→        .conversation-header {
   241→            padding: 16px 24px;
   242→            background: #161b22;
   243→            border-bottom: 1px solid #30363d;
   244→            display: flex;
   245→            justify-content: space-between;
   246→            align-items: center;
   247→        }
   248→
   249→        .conversation-header h2 {
   250→            font-size: 15px;
   251→            font-weight: 600;
   252→            color: #f0f6fc;
   253→            margin: 0;
   254→        }
   255→
   256→        .conversation-header .meta {
   257→            font-size: 12px;
   258→            color: #6e7681;
   259→        }
   260→
   261→        .header-controls {
   262→            display: flex;
   263→            align-items: center;
   264→            gap: 12px;
   265→        }
   266→
   267→        .filter-toggle {
   268→            display: flex;
   269→            align-items: center;
   270→            gap: 6px;
   271→            padding: 6px 12px;
   272→            background: #21262d;
   273→            border: 1px solid #30363d;
   274→            border-radius: 6px;
   275→            color: #c9d1d9;
   276→            font-size: 12px;
   277→            cursor: pointer;
   278→            transition: all 0.2s;
   279→        }
   280→
   281→        .filter-toggle:hover {
   282→            background: #30363d;
   283→            border-color: #484f58;
   284→        }
   285→
   286→        .filter-toggle.active {
   287→            background: #1f6feb;
   288→            border-color: #1f6feb;
   289→            color: #fff;
   290→        }
   291→
   292→        /* User-only filter mode */
   293→        .messages-container.user-only .message:not(.user) {
   294→            display: none;
   295→        }
   296→
   297→        .messages-container.user-only .message.user {
   298→            display: block;
   299→            cursor: pointer;
   300→        }
   301→
   302→        .messages-container.user-only .message.user:hover {
   303→            background: #1c2128;
   304→        }
   305→
   306→        /* When a user message is expanded, show following non-user messages */
   307→        .messages-container.user-only .message.user.expanded {
   308→            background: #1f6feb22;
   309→        }
   310→
   311→        .messages-container.user-only .message.expanded-child {
   312→            display: block;
   313→        }
   314→
   315→        .messages-container {
   316→            flex: 1;
   317→            overflow-y: auto;
   318→            padding: 8px 12px;
   319→        }
   320→
   321→        .message {
   322→            margin-bottom: 6px;
   323→            max-width: 100%;
   324→        }
   325→
   326→        .message-header {
   327→            display: flex;
   328→            align-items: center;
   329→            gap: 4px;
   330→            margin-bottom: 2px;
   331→        }
   332→
   333→        .message-role {
   334→            font-size: 10px;
   335→            font-weight: 600;
   336→            padding: 1px 5px;
   337→            border-radius: 3px;
   338→        }
   339→
   340→        .message-role.user {
   341→            background: #1f6feb;
   342→            color: #fff;
   343→        }
   344→
   345→        .message-role.assistant {
   346→            background: #238636;
   347→            color: #fff;
   348→        }
   349→
   350→        .message-role.system {
   351→            background: #30363d;
   352→            color: #8b949e;
   353→        }
   354→
   355→        .message-role.tool {
   356→            background: #a371f7;
   357→            color: #fff;
   358→        }
   359→
   360→        .message-time {
   361→            font-size: 11px;
   362→            color: #6e7681;
   363→        }
   364→
   365→        .message-content {
   366→            background: #161b22;
   367→            padding: 4px 8px;
   368→            border-radius: 3px;
   369→            font-size: 12px;
   370→            line-height: 1.35;
   371→            white-space: pre-wrap;
   372→            word-break: break-word;
   373→            border: 1px solid #30363d;
   374→        }
   375→
   376→        .message.user .message-content {
   377→            border-left: 3px solid #1f6feb;
   378→        }
   379→
   380→        .message.assistant .message-content {
   381→            border-left: 3px solid #238636;
   382→        }
   383→
   384→        .message.selected > .message-content {
   385→            outline: 2px solid #58a6ff;
   386→            outline-offset: -2px;
   387→        }
   388→
   389→        .hook-output {
   390→            margin-top: 8px;
   391→            padding: 8px;
   392→            background: #1c2128;
   393→            border-radius: 4px;
   394→            font-size: 11px;
   395→            white-space: pre-wrap;
   396→            border-left: 2px solid #f0883e;
   397→        }
   398→
   399→        /* When message content only has tool boxes, reduce padding */
   400→        .message-content.tools-only {
   401→            padding: 2px 4px;
   402→            background: transparent;
   403→            border: none;
   404→            border-left: 3px solid #238636;
   405→        }
   406→
   407→        .tool-use {
   408→            margin: 2px 0;
   409→            background: #21262d;
   410→            border-radius: 3px;
   411→            border: 1px solid #30363d;
   412→            overflow: hidden;
   413→        }
   414→
   415→        .tool-header {
   416→            padding: 2px 6px;
   417→            background: #30363d;
   418→            font-size: 11px;
   419→            font-weight: 500;
   420→            color: #a371f7;
   421→        }
   422→
   423→        .tool-input {
   424→            padding: 4px 6px;
   425→            font-family: ui-monospace, SFMono-Regular, 'SF Mono', Menlo, monospace;
   426→            font-size: 12px;
   427→            overflow-x: auto;
   428→            max-height: 200px;
   429→            overflow-y: auto;
