   442→            padding: 1px 4px;
   443→            border-radius: 3px;
   444→        }
   445→
   446→        .tool-description {
   447→            color: #8b949e;
   448→            font-style: italic;
   449→            font-size: 11px;
   450→        }
   451→
   452→        .tool-code-preview {
   453→            background: #161b22;
   454→            padding: 4px 6px;
   455→            border-radius: 3px;
   456→            margin: 4px 0;
   457→            max-height: 100px;
   458→            overflow: auto;
   459→            white-space: pre-wrap;
   460→            font-size: 11px;
   461→            border-left: 2px solid #30363d;
   462→        }
   463→
   464→        .tool-code-preview.tool-old {
   465→            border-left-color: #f85149;
   466→            background: #2d1515;
   467→        }
   468→
   469→        .tool-code-preview.tool-new {
   470→            border-left-color: #3fb950;
   471→            background: #1b2e1b;
   472→        }
   473→
   474→        .tool-json {
   475→            margin: 0;
   476→            white-space: pre-wrap;
   477→        }
   478→
   479→        .todo-completed {
   480→            color: #3fb950;
   481→        }
   482→
   483→        .todo-in_progress {
   484→            color: #f0883e;
   485→        }
   486→
   487→        .todo-pending {
   488→            color: #8b949e;
   489→        }
   490→
   491→        .tool-url {
   492→            color: #58a6ff;
   493→            word-break: break-all;
   494→        }
   495→
   496→        .tool-result {
   497→            margin: 3px 0;
   498→            background: #21262d;
   499→            border-radius: 3px;
   500→            border: 1px solid #30363d;
   501→            overflow: hidden;
   502→        }
   503→
   504→        .tool-result-header {
   505→            padding: 2px 6px;
   506→            background: #21262d;
   507→            font-size: 10px;
   508→            font-weight: 500;
   509→            color: #238636;
   510→            border-bottom: 1px solid #30363d;
   511→        }
   512→
   513→        .tool-result.error {
   514→            border-color: #f85149;
   515→        }
   516→
   517→        .tool-result.error .tool-result-header {
   518→            color: #f85149;
   519→            background: #3d1f1f;
   520→        }
   521→
   522→        .tool-result.error .tool-result-content {
   523→            background: #2d1515;
