   661→            .hamburger {
   662→                display: block;
   663→            }
   664→
   665→            .sidebar {
   666→                position: fixed;
   667→                top: 0;
   668→                left: 0;
   669→                bottom: 0;
   670→                z-index: 1000;
   671→                transform: translateX(-100%);
   672→                transition: transform 0.3s ease;
   673→            }
   674→
   675→            .sidebar.open {
   676→                transform: translateX(0);
   677→            }
   678→
   679→            .sidebar-overlay.open {
   680→                display: block;
   681→            }
   682→
   683→            .main-content {
   684→                width: 100%;
   685→            }
   686→
   687→            .conversation-header {
   688→                padding: 12px 16px;
   689→            }
   690→
   691→            .conversation-header h2 {
   692→                font-size: 14px;
   693→            }
   694→
   695→            .messages-container {
   696→                padding: 8px;
   697→            }
   698→        }
   699→    </style>
   700→</head>
   701→<body>
   702→    <div id="mouseTooltip"></div>
   703→    <div class="sidebar-overlay" id="sidebarOverlay" onclick="toggleSidebar()"></div>
   704→    <div class="container">
   705→        <div class="sidebar" id="sidebar">
   706→            <div class="sidebar-header">
   707→                <h1>Claude Code Conversations</h1>
   708→            </div>
   709→            <div class="list-container" id="listContainer">
   710→                <div class="loading">Loading...</div>
   711→            </div>
   712→        </div>
   713→
   714→        <div class="main-content">
   715→            <div class="conversation-header" id="conversationHeader">
   716→                <div style="display: flex; align-items: center;">
   717→                    <button class="hamburger" onclick="toggleSidebar()">☰</button>
   718→                    <div>
   719→                        <h2 id="conversationTitle">Select a conversation</h2>
   720→                        <div class="meta" id="conversationMeta"></div>
   721→                    </div>
   722→                </div>
   723→                <div class="header-controls">
   724→                    <button class="filter-toggle" id="userOnlyToggle" onclick="toggleUserOnly()">
   725→                        User messages only
   726→                    </button>
   727→                </div>
   728→            </div>
   729→
