  1101→        function parseAgentConversation(filename, content) {
  1102→            const lines = content.trim().split('\n');
  1103→            const messages = [];
  1104→            let summary = '';
  1105→            let agentId = '';
  1106→
  1107→            lines.forEach(line => {
  1108→                try {
  1109→                    const obj = JSON.parse(line);
  1110→                    if (obj.type === 'summary') {
  1111→                        summary = obj.summary;
  1112→                    } else if (obj.type === 'user' || obj.type === 'assistant') {
  1113→                        if (!agentId && obj.agentId) agentId = obj.agentId;
  1114→                        // Skip "Warmup" messages
  1115→                        if (obj.type === 'user' && obj.message?.content === 'Warmup') {
  1116→                            return;
  1117→                        }
  1118→                        messages.push(obj);
  1119→                    }
  1120→                } catch (e) {}
  1121→            });
  1122→
  1123→            return { filename, summary, agentId, messages };
  1124→        }
