  1126→        function parseConversation(filename, content) {
  1127→            const lines = content.trim().split('\n');
  1128→            const messages = [];
  1129→            let summary = '';
  1130→            let sessionId = '';
  1131→            let gitBranch = '';
  1132→            let agentId = '';
  1133→            let isAgent = filename.includes('agent-');
  1134→
  1135→            lines.forEach(line => {
  1136→                try {
  1137→                    const obj = JSON.parse(line);
  1138→                    if (obj.type === 'summary') {
  1139→                        summary = obj.summary;
  1140→                    } else if (obj.type === 'user' || obj.type === 'assistant') {
  1141→                        if (!sessionId && obj.sessionId) sessionId = obj.sessionId;
  1142→                        if (!gitBranch && obj.gitBranch) gitBranch = obj.gitBranch;
  1143→                        if (!agentId && obj.agentId) agentId = obj.agentId;
  1144→
  1145→                        // Skip internal "Warmup" messages in agent sessions
  1146→                        if (isAgent && obj.type === 'user' && obj.message?.content === 'Warmup') {
  1147→                            return;
  1148→                        }
  1149→                        messages.push(obj);
  1150→                    } else if (obj.type === 'system') {
  1151→                        messages.push(obj);
  1152→                    }
  1153→                } catch (e) {}
  1154→            });
  1155→
  1156→            const id = filename.split('/').pop().replace('.jsonl', '');
  1157→            currentConversation = id;
  1158→            conversations[id] = { filename, summary, sessionId, gitBranch, agentId, isAgent, messages };
  1159→        }
