  1207→        function renderMessage(msg, showTools) {
  1208→            const time = msg.timestamp ? new Date(msg.timestamp).toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'}) : '';
  1209→
  1210→            // Check if this is a tool_result message (comes as type: "user" but is really tool output)
  1211→            const isToolResult = msg.type === 'user' &&
  1212→                Array.isArray(msg.message?.content) &&
  1213→                msg.message.content.some(c => c.type === 'tool_result');
  1214→
  1215→            // Check if this is a meta message (isMeta: true indicates system-injected, not real user)
  1216→            const isMeta = msg.isMeta === true;
  1217→
  1218→            // Check if this is a continuation message from context overflow (fallback text check)
  1219→            const isContinuation = msg.type === 'user' &&
  1220→                typeof msg.message?.content === 'string' &&
  1221→                msg.message.content.startsWith('This session is being continued from a previous conversation');
  1222→
  1223→            const role = isToolResult ? 'tool' : ((isMeta || isContinuation) ? 'system' : (msg.type === 'user' ? 'user' : (msg.type === 'assistant' ? 'assistant' : 'system')));
  1224→
  1225→            let content = '';
  1226→
  1227→            // Handle system messages (different structure)
  1228→            if (msg.type === 'system') {
  1229→                const parts = [];
  1230→                if (msg.subtype) parts.push(`[${msg.subtype}]`);
  1231→                if (msg.hookInfos && msg.hookInfos.length > 0) {
  1232→                    parts.push(`Hooks: ${msg.hookInfos.map(h => h.command).join(', ')}`);
  1233→                }
  1234→                if (msg.stopReason) parts.push(`Stop: ${msg.stopReason}`);
  1235→                if (msg.level) parts.push(`Level: ${msg.level}`);
  1236→                content = escapeHtml(parts.join(' | ') || 'System event');
  1237→                // Show hook output/errors if present
  1238→                if (msg.hookErrors && msg.hookErrors.length > 0) {
  1239→                    content += '<div class="hook-output">' + msg.hookErrors.map(e => escapeHtml(e)).join('<hr>') + '</div>';
  1240→                }
  1241→            } else if (msg.message) {
  1242→                if (typeof msg.message.content === 'string') {
  1243→                    content = escapeHtml(msg.message.content);
  1244→                } else if (Array.isArray(msg.message.content)) {
  1245→                    content = msg.message.content.map(c => {
  1246→                        if (c.type === 'text') {
  1247→                            return escapeHtml(c.text);
  1248→                        } else if (c.type === 'image' && c.source) {
  1249→                            // Handle base64 images
  1250→                            const src = c.source.type === 'base64'
  1251→                                ? `data:${c.source.media_type};base64,${c.source.data}`
  1252→                                : c.source.url;
  1253→                            return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
  1254→                        } else if (c.type === 'tool_use' && showTools) {
  1255→                            return renderToolUse(c);
  1256→                        } else if (c.type === 'tool_result' && showTools) {
  1257→                            return renderToolResult(c, msg.uuid);
  1258→                        }
  1259→                        return '';
  1260→                    }).join('');
  1261→                }
  1262→            }
  1263→
  1264→            if (!content.trim()) return '';
  1265→
  1266→            // Build tooltip data with ALL non-id attributes
  1267→            const tooltipData = {};
